php foreach($responsibles as$responsible): ?><option value="<?= (int)$responsible['id'] ?>"<?= selected(old('responsable_id'),$responsible['id']) ?>><?= e($responsible['nombre']) ?></option><?php endforeach; ?></select><label class="label mt-3">Fecha compromiso</label><input type="date" name="fecha_compromiso" class="input" value="<?= e(old('fecha_compromiso')) ?>"></div><div class="sm:col-span-2 lg:col-span-3 flex justify-end"><button class="btn-primary" type="submit">Guardar caso reservado</button></div></form></details>
