t name="estado" class="input"><option>Realizada</option><option>Cancelada</option></select><textarea name="participantes" class="input min-h-20" placeholder="Participantes reales *"><?= e($meeting['participantes']) ?></textarea><textarea name="compromisos" class="input min-h-20" placeholder="Compromisos / observaciones / motivo de cancelación *"></textarea><input name="acta_referencia" class="input" placeholder="Referencia real del acta *"><label class="flex items-start gap-2 text-[11px]"><input type="checkbox" name="quorum_verificado" value="1" class="mt-0.5"><span>Confirmo asistencia y quórum contra el acta real.</span></label><input type="date" name="proxima_fecha" class="input" value="<?= e($meeting['proxima_fecha']) ?>"><button class="btn-secondary w-full" type="submit">Guardar resultado</button></form></details><?php else: ?><p class="mt-2 text-xs text-slate-500">Cancelación: <?= e($meeting['compromisos']) ?></p><?php endif; ?><details class="mt-3 rounded-xl bg-slate-50 p-3"><summary class="cursor-pointer text-[11px] font-semibold text-slate-600">Soportes reservados (<?= count($supports) ?>)</summary><div class="mt-3 space-y-2"><?php foreach($supports as$support): ?><div class="flex items-center justify-between gap-2 text-[11px]"><span><?= e($support['titulo']) ?><span class="block text-[9px] text-slate-400"><?= e($support['estado_revision']) ?></span></span><a href="<?= e(url('/soportes-reservados/'.$support['id'].'/descargar')) ?>" class="text-link">Descargar</a><?php if($support['estado_revision']!=='Revisado'): ?><form method="post" action="<?= e(url('/soportes-reservados/'.$support['id'].'/revision')) ?>"><?= csrf_field() ?><input type="hidden" name="return_url" value="<?= e('/convivencia#reunion-'.$meeting['id']) ?>"><button class="text-link" type="submit">Revisar</button></form><?php endif; ?></div><?php endforeach; ?></div><form method="post" enctype="multipart/form-data" action="<?= e(url('/soportes-reservados')) ?>" class="mt-3 space-y-2"><?= csrf_fi